import { z } from 'zod';

export type OpenAICompatibleConnectionConfig = {
	apiKey?: string;
	baseUrl: string;
	headers?: Record<string, string>;
	model: string;
};

export type OpenAICompatibleConnectionDraft = OpenAICompatibleConnectionConfig;

export type ConnectionValidationIssue = {
	field: 'apiKey' | 'baseUrl' | 'headers' | 'model';
	message: string;
};

export type ConnectionValidationResult =
	| { success: true; value: OpenAICompatibleConnectionConfig }
	| { issues: ConnectionValidationIssue[]; success: false };

const baseUrlSchema = z
	.string()
	.trim()
	.min(1, '请输入 Base URL。')
	.max(2048, 'Base URL 过长。')
	.refine(isAllowedBaseUrl, 'Base URL 必须是有效的 HTTP 或 HTTPS 地址，且不能包含凭据、查询参数或片段。')
	.transform(normalizeOpenAICompatibleBaseUrl);

const connectionSchema = z
	.object({
		apiKey: z
			.string()
			.max(16 * 1024, 'API Key 过长。')
			.optional(),
		baseUrl: baseUrlSchema,
		headers: z
			.record(z.string().min(1).max(128), z.string().max(8 * 1024))
			.refine((headers) => Object.keys(headers).length <= 64, '请求头不能超过 64 项。')
			.refine(
				(headers) => Object.entries(headers).every(([name, value]) => !/[\r\n]/u.test(name) && !/[\r\n]/u.test(value)),
				'请求头不能包含换行符。',
			)
			.optional(),
		model: z.string().trim().min(1, '请输入模型。').max(256, '模型名称过长。'),
	})
	.strict();

export function normalizeOpenAICompatibleBaseUrl(value: string): string {
	return value.replace(/\/+$/u, '');
}

export function validateOpenAICompatibleBaseUrl(
	value: string,
): { success: true; value: string } | { message: string; success: false } {
	const result = baseUrlSchema.safeParse(value);
	return result.success
		? { success: true, value: result.data }
		: { success: false, message: result.error.issues[0]?.message ?? 'Base URL 无效。' };
}

export function validateOpenAICompatibleConnection(input: unknown): ConnectionValidationResult {
	const result = connectionSchema.safeParse(input);
	if (result.success) return { success: true, value: result.data };
	return {
		success: false,
		issues: result.error.issues.slice(0, 8).map((issue) => ({
			field: toConnectionField(issue.path[0]),
			message: issue.message,
		})),
	};
}

export function requireOpenAICompatibleConnection(input: unknown): OpenAICompatibleConnectionConfig {
	const result = validateOpenAICompatibleConnection(input);
	if (result.success) return result.value;
	throw new Error(result.issues[0]?.message ?? '连接配置无效。');
}

export function sameOpenAICompatibleConnection(
	left: OpenAICompatibleConnectionConfig,
	right: OpenAICompatibleConnectionConfig,
): boolean {
	if (left.baseUrl !== right.baseUrl || left.apiKey !== right.apiKey || left.model !== right.model) return false;
	const leftHeaders = left.headers ?? {};
	const rightHeaders = right.headers ?? {};
	const leftKeys = Object.keys(leftHeaders);
	const rightKeys = Object.keys(rightHeaders);
	return leftKeys.length === rightKeys.length && leftKeys.every((key) => rightHeaders[key] === leftHeaders[key]);
}

function isAllowedBaseUrl(value: string): boolean {
	try {
		const url = new URL(value);
		return (
			(url.protocol === 'http:' || url.protocol === 'https:') &&
			url.hostname.length > 0 &&
			url.username.length === 0 &&
			url.password.length === 0 &&
			url.search.length === 0 &&
			url.hash.length === 0
		);
	} catch {
		return false;
	}
}

function toConnectionField(value: PropertyKey | undefined): ConnectionValidationIssue['field'] {
	if (value === 'apiKey' || value === 'headers' || value === 'model') return value;
	return 'baseUrl';
}

export const AGENT_SAFE_ERROR_MAX_LENGTH = 320;

export function toSafeAgentError(error: unknown, secrets: readonly string[] = []): Error {
	if (isAbortError(error)) return new DOMException('操作已取消。', 'AbortError');
	let message = error instanceof Error ? error.message : typeof error === 'string' ? error : '请求失败。';
	for (const secret of secrets) {
		if (secret.length > 0) message = message.split(secret).join('[已隐藏]');
	}
	message = message
		.replace(/\bBearer\s+[^\s,;]+/giu, 'Bearer [已隐藏]')
		.replace(/\b(authorization|api[-_ ]?key)\s*[:=]\s*[^\s,;]+/giu, '$1=[已隐藏]')
		.replace(/https?:\/\/[^\s)\]}>'"]+/giu, '[服务地址]')
		.replace(/[\r\n\t]+/gu, ' ')
		.trim();
	if (message.length === 0) message = '请求失败。';
	if (message.length > AGENT_SAFE_ERROR_MAX_LENGTH) message = `${message.slice(0, AGENT_SAFE_ERROR_MAX_LENGTH - 1)}…`;
	return new Error(message);
}

export function isAbortError(error: unknown): boolean {
	return error instanceof DOMException
		? error.name === 'AbortError'
		: error instanceof Error && error.name === 'AbortError';
}

import { z } from 'zod';
import { validateOpenAICompatibleBaseUrl } from './connection-config';

export const OPENAI_MODEL_LIST_DEFAULT_TIMEOUT_MS = 10_000;
export const OPENAI_MODEL_LIST_DEFAULT_MAX_BYTES = 1024 * 1024;
export const OPENAI_MODEL_LIST_MAX_MODELS = 1000;

export type OpenAICompatibleModel = {
	created?: number;
	id: string;
	ownedBy?: string;
};

export type OpenAICompatibleModelListConfig = {
	apiKey?: string;
	baseUrl: string;
	headers?: Record<string, string>;
};

export type OpenAICompatibleModelListOptions = {
	fetch?: typeof globalThis.fetch;
	maxResponseBytes?: number;
	signal?: AbortSignal;
	timeoutMs?: number;
};

export class OpenAICompatibleModelListError extends Error {
	readonly code:
		| 'aborted'
		| 'connection'
		| 'invalid-config'
		| 'invalid-response'
		| 'response-too-large'
		| 'status'
		| 'timeout';

	constructor(code: OpenAICompatibleModelListError['code'], message: string) {
		super(message);
		this.name = 'OpenAICompatibleModelListError';
		this.code = code;
	}
}

const modelSchema = z
	.object({
		created: z.number().int().nonnegative().optional(),
		id: z.string().min(1).max(256),
		object: z.literal('model').optional(),
		owned_by: z.string().max(256).optional(),
	})
	.passthrough();
const modelListSchema = z
	.object({ object: z.literal('list'), data: z.array(modelSchema).max(OPENAI_MODEL_LIST_MAX_MODELS) })
	.passthrough();

export async function listOpenAICompatibleModels(
	config: OpenAICompatibleModelListConfig,
	options: OpenAICompatibleModelListOptions = {},
): Promise<OpenAICompatibleModel[]> {
	const baseUrl = validateOpenAICompatibleBaseUrl(config.baseUrl);
	if (!baseUrl.success) throw new OpenAICompatibleModelListError('invalid-config', baseUrl.message);
	if (options.signal?.aborted) {
		throw new OpenAICompatibleModelListError('aborted', '模型列表请求已取消。');
	}
	const timeoutMs = resolveBound(options.timeoutMs, OPENAI_MODEL_LIST_DEFAULT_TIMEOUT_MS, 60_000);
	const maxBytes = resolveBound(options.maxResponseBytes, OPENAI_MODEL_LIST_DEFAULT_MAX_BYTES, 4 * 1024 * 1024);
	const controller = new AbortController();
	let timedOut = false;
	const abortFromCaller = () => controller.abort(options.signal?.reason);
	options.signal?.addEventListener('abort', abortFromCaller, { once: true });
	const timer = setTimeout(() => {
		timedOut = true;
		controller.abort();
	}, timeoutMs);
	const headers = new Headers(config.headers);
	headers.set('Accept', 'application/json');
	headers.delete('Authorization');
	if (config.apiKey?.trim()) headers.set('Authorization', `Bearer ${config.apiKey}`);
	try {
		const response = await (options.fetch ?? globalThis.fetch)(`${baseUrl.value}/models`, {
			headers,
			method: 'GET',
			signal: controller.signal,
		});
		if (!response.ok) {
			throw new OpenAICompatibleModelListError('status', `模型列表请求失败（HTTP ${response.status}）。`);
		}
		const contentType = response.headers.get('content-type');
		if (contentType && !/\bapplication\/(?:[\w.+-]+\+)?json\b/iu.test(contentType)) {
			throw new OpenAICompatibleModelListError('invalid-response', '模型列表响应不是 JSON。');
		}
		const text = await readBoundedResponseText(response, maxBytes);
		let parsed: unknown;
		try {
			parsed = JSON.parse(text);
		} catch {
			throw new OpenAICompatibleModelListError('invalid-response', '模型列表响应不是有效 JSON。');
		}
		const validated = modelListSchema.safeParse(parsed);
		if (!validated.success) {
			throw new OpenAICompatibleModelListError('invalid-response', '模型列表响应不符合 OpenAI models list 格式。');
		}
		const seen = new Set<string>();
		return validated.data.data.flatMap((model) => {
			if (seen.has(model.id)) return [];
			seen.add(model.id);
			return [{ id: model.id, created: model.created, ownedBy: model.owned_by }];
		});
	} catch (error) {
		if (error instanceof OpenAICompatibleModelListError) throw error;
		if (controller.signal.aborted) {
			throw new OpenAICompatibleModelListError(
				timedOut ? 'timeout' : 'aborted',
				timedOut ? '模型列表请求超时。' : '模型列表请求已取消。',
			);
		}
		throw new OpenAICompatibleModelListError('connection', '无法连接到模型服务。');
	} finally {
		clearTimeout(timer);
		options.signal?.removeEventListener('abort', abortFromCaller);
	}
}

async function readBoundedResponseText(response: Response, maxBytes: number): Promise<string> {
	const contentLength = Number(response.headers.get('content-length'));
	if (Number.isFinite(contentLength) && contentLength > maxBytes) {
		throw new OpenAICompatibleModelListError('response-too-large', '模型列表响应超过大小限制。');
	}
	if (!response.body) return '';
	const reader = response.body.getReader();
	const chunks: Uint8Array[] = [];
	let total = 0;
	try {
		while (true) {
			const { done, value } = await reader.read();
			if (done) break;
			total += value.byteLength;
			if (total > maxBytes) {
				await reader.cancel();
				throw new OpenAICompatibleModelListError('response-too-large', '模型列表响应超过大小限制。');
			}
			chunks.push(value);
		}
	} finally {
		reader.releaseLock();
	}
	const bytes = new Uint8Array(total);
	let offset = 0;
	for (const chunk of chunks) {
		bytes.set(chunk, offset);
		offset += chunk.byteLength;
	}
	try {
		return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
	} catch {
		throw new OpenAICompatibleModelListError('invalid-response', '模型列表响应不是有效 UTF-8。');
	}
}

function resolveBound(value: number | undefined, fallback: number, maximum: number): number {
	return Number.isFinite(value) && value !== undefined && value > 0 ? Math.min(Math.floor(value), maximum) : fallback;
}

import type { FileUIPart } from 'ai';
import { isAbortError } from './safe-error';

export const AGENT_RUNTIME_DEFAULT_MAX_FILES = 5;
export const AGENT_RUNTIME_DEFAULT_MAX_FILE_SIZE = 10 * 1024 * 1024;
export const AGENT_RUNTIME_DEFAULT_MAX_TOTAL_SIZE = 20 * 1024 * 1024;

export type AgentRuntimeFileLimits = {
	maxFileSize?: number;
	maxFiles?: number;
	maxTotalSize?: number;
};

export type AgentRuntimeResolvedFileLimits = {
	maxFileSize: number;
	maxFiles: number;
	maxTotalSize: number;
};

export class AgentRuntimeFileError extends Error {
	readonly code: 'aborted' | 'file-count' | 'file-read' | 'file-size' | 'total-size' | 'unsupported-type';
	readonly file?: File;

	constructor(code: AgentRuntimeFileError['code'], message: string, file?: File) {
		super(message);
		this.name = 'AgentRuntimeFileError';
		this.code = code;
		this.file = file;
	}
}

export function resolveAgentRuntimeFileLimits(limits: AgentRuntimeFileLimits = {}): AgentRuntimeResolvedFileLimits {
	return {
		maxFiles: resolveLimit(limits.maxFiles, AGENT_RUNTIME_DEFAULT_MAX_FILES, 20),
		maxFileSize: resolveLimit(limits.maxFileSize, AGENT_RUNTIME_DEFAULT_MAX_FILE_SIZE, 64 * 1024 * 1024),
		maxTotalSize: resolveLimit(limits.maxTotalSize, AGENT_RUNTIME_DEFAULT_MAX_TOTAL_SIZE, 128 * 1024 * 1024),
	};
}

export async function convertAgentFilesToUIParts(
	files: readonly File[],
	limits: AgentRuntimeFileLimits = {},
	signal?: AbortSignal,
): Promise<FileUIPart[]> {
	const resolved = resolveAgentRuntimeFileLimits(limits);
	validateFiles(files, resolved);
	if (signal?.aborted) throw abortedError();
	const parts: FileUIPart[] = [];
	for (const file of files) {
		if (signal?.aborted) throw abortedError();
		parts.push({
			type: 'file',
			filename: file.name || undefined,
			mediaType: resolveMediaType(file),
			url: await readFileAsDataUrl(file, signal),
		});
	}
	return parts;
}

function validateFiles(files: readonly File[], limits: AgentRuntimeResolvedFileLimits) {
	if (files.length > limits.maxFiles) {
		throw new AgentRuntimeFileError('file-count', `最多发送 ${limits.maxFiles} 个附件。`);
	}
	let total = 0;
	for (const file of files) {
		if (!Number.isFinite(file.size) || file.size < 0 || file.size > limits.maxFileSize) {
			throw new AgentRuntimeFileError('file-size', `${file.name || '未命名文件'} 超过单个附件大小限制。`, file);
		}
		const mediaType = resolveMediaType(file);
		const topLevel = mediaType.split('/', 1)[0];
		if (topLevel !== 'application' && topLevel !== 'audio' && topLevel !== 'image' && topLevel !== 'text') {
			throw new AgentRuntimeFileError('unsupported-type', `${file.name || '未命名文件'} 的类型不受支持。`, file);
		}
		total += file.size;
		if (total > limits.maxTotalSize) {
			throw new AgentRuntimeFileError('total-size', '附件总大小超过限制。');
		}
	}
}

function resolveMediaType(file: File): string {
	return file.type.trim().toLowerCase() || 'application/octet-stream';
}

function readFileAsDataUrl(file: File, signal?: AbortSignal): Promise<string> {
	return new Promise((resolve, reject) => {
		const reader = new FileReader();
		const abort = () => reader.abort();
		const cleanup = () => signal?.removeEventListener('abort', abort);
		signal?.addEventListener('abort', abort, { once: true });
		reader.onload = () => {
			cleanup();
			if (typeof reader.result === 'string') resolve(reader.result);
			else reject(new AgentRuntimeFileError('file-read', `无法读取 ${file.name || '附件'}。`, file));
		};
		reader.onerror = () => {
			cleanup();
			reject(new AgentRuntimeFileError('file-read', `无法读取 ${file.name || '附件'}。`, file));
		};
		reader.onabort = () => {
			cleanup();
			reject(abortedError());
		};
		try {
			reader.readAsDataURL(file);
		} catch (error) {
			cleanup();
			reject(
				isAbortError(error)
					? abortedError()
					: new AgentRuntimeFileError('file-read', `无法读取 ${file.name || '附件'}。`, file),
			);
		}
	});
}

function abortedError() {
	return new AgentRuntimeFileError('aborted', '附件读取已取消。');
}

function resolveLimit(value: number | undefined, fallback: number, maximum: number) {
	return Number.isFinite(value) && value !== undefined && value > 0 ? Math.min(Math.floor(value), maximum) : fallback;
}

export type OpenAICompatibleDirectTransportTimeouts = {
	chunkMs?: number;
	stepMs?: number;
	toolMs?: number;
	totalMs?: number;
};

export type OpenAICompatibleDirectTransportLimits = {
	maxOutputTokens?: number;
	maxResponseBytes?: number;
	maxResponseChunks?: number;
	maxRetries?: number;
	maxStreamChunks?: number;
	maxStreamProjectionBytes?: number;
	timeout?: OpenAICompatibleDirectTransportTimeouts;
};

export type ResolvedOpenAICompatibleDirectTransportLimits = {
	maxOutputTokens: number;
	maxResponseBytes: number;
	maxResponseChunks: number;
	maxRetries: number;
	maxStreamChunks: number;
	maxStreamProjectionBytes: number;
	timeout: Required<OpenAICompatibleDirectTransportTimeouts>;
};

export const OPENAI_COMPATIBLE_DIRECT_TRANSPORT_CEILINGS: ResolvedOpenAICompatibleDirectTransportLimits = {
	maxOutputTokens: 8_192,
	maxResponseBytes: 8 * 1024 * 1024,
	maxResponseChunks: 16_384,
	maxRetries: 2,
	maxStreamChunks: 16_384,
	maxStreamProjectionBytes: 8 * 1024 * 1024,
	timeout: {
		chunkMs: 20_000,
		stepMs: 60_000,
		toolMs: 30_000,
		totalMs: 120_000,
	},
};

export function resolveOpenAICompatibleDirectTransportLimits(
	limits: OpenAICompatibleDirectTransportLimits = {},
): ResolvedOpenAICompatibleDirectTransportLimits {
	return {
		maxOutputTokens: boundedInteger(
			limits.maxOutputTokens,
			OPENAI_COMPATIBLE_DIRECT_TRANSPORT_CEILINGS.maxOutputTokens,
			1,
			'maxOutputTokens',
		),
		maxResponseBytes: boundedInteger(
			limits.maxResponseBytes,
			OPENAI_COMPATIBLE_DIRECT_TRANSPORT_CEILINGS.maxResponseBytes,
			1,
			'maxResponseBytes',
		),
		maxResponseChunks: boundedInteger(
			limits.maxResponseChunks,
			OPENAI_COMPATIBLE_DIRECT_TRANSPORT_CEILINGS.maxResponseChunks,
			1,
			'maxResponseChunks',
		),
		maxRetries: boundedInteger(
			limits.maxRetries,
			OPENAI_COMPATIBLE_DIRECT_TRANSPORT_CEILINGS.maxRetries,
			0,
			'maxRetries',
		),
		maxStreamChunks: boundedInteger(
			limits.maxStreamChunks,
			OPENAI_COMPATIBLE_DIRECT_TRANSPORT_CEILINGS.maxStreamChunks,
			1,
			'maxStreamChunks',
		),
		maxStreamProjectionBytes: boundedInteger(
			limits.maxStreamProjectionBytes,
			OPENAI_COMPATIBLE_DIRECT_TRANSPORT_CEILINGS.maxStreamProjectionBytes,
			1,
			'maxStreamProjectionBytes',
		),
		timeout: {
			chunkMs: timeoutValue(limits.timeout?.chunkMs, 'chunkMs'),
			stepMs: timeoutValue(limits.timeout?.stepMs, 'stepMs'),
			toolMs: timeoutValue(limits.timeout?.toolMs, 'toolMs'),
			totalMs: timeoutValue(limits.timeout?.totalMs, 'totalMs'),
		},
	};
}

export function wrapBoundedResponse(
	response: Response,
	limits: Pick<ResolvedOpenAICompatibleDirectTransportLimits, 'maxResponseBytes' | 'maxResponseChunks'>,
): Response {
	if (!response.body) return response;
	const reader = response.body.getReader();
	let bytes = 0;
	let chunks = 0;
	const body = new ReadableStream<Uint8Array>({
		async pull(controller) {
			try {
				const result = await reader.read();
				if (result.done) {
					controller.close();
					return;
				}
				chunks += 1;
				bytes += result.value.byteLength;
				if (chunks > limits.maxResponseChunks || bytes > limits.maxResponseBytes) {
					await reader.cancel('response limit exceeded').catch(() => undefined);
					controller.error(new Error('模型响应超过客户端安全限制。'));
					return;
				}
				controller.enqueue(result.value);
			} catch (error) {
				controller.error(error);
			}
		},
		cancel(reason) {
			return reader.cancel(reason);
		},
	});
	return new Response(body, {
		headers: response.headers,
		status: response.status,
		statusText: response.statusText,
	});
}

function timeoutValue(value: number | undefined, name: keyof OpenAICompatibleDirectTransportTimeouts): number {
	return boundedInteger(value, OPENAI_COMPATIBLE_DIRECT_TRANSPORT_CEILINGS.timeout[name]!, 1, `timeout.${name}`);
}

function boundedInteger(value: number | undefined, ceiling: number, minimum: number, name: string): number {
	if (value === undefined) return ceiling;
	if (!Number.isInteger(value) || value < minimum || value > ceiling) {
		throw new Error(`${name} 必须是 ${minimum} 到 ${ceiling} 之间的整数。`);
	}
	return value;
}

import { createOpenAICompatible } from '@ai-sdk/openai-compatible';
import {
	type ChatTransport,
	DirectChatTransport,
	type Instructions,
	isStepCount,
	ToolLoopAgent,
	type ToolLoopAgentSettings,
	type ToolSet,
	type UIMessage,
	type UIMessageChunk,
} from 'ai';
import { measureAgentRuntimeValue } from '../agent-chat/runtime-message-validation';
import type { OpenAICompatibleConnectionConfig } from './connection-config';
import { requireOpenAICompatibleConnection } from './connection-config';
import {
	type OpenAICompatibleDirectTransportLimits,
	type ResolvedOpenAICompatibleDirectTransportLimits,
	resolveOpenAICompatibleDirectTransportLimits,
	wrapBoundedResponse,
} from './direct-transport-limits';
import { toSafeAgentError } from './safe-error';

export type OpenAICompatibleDirectTransportOptions = {
	connection: OpenAICompatibleConnectionConfig;
	fetch?: typeof globalThis.fetch;
	instructions?: Instructions;
	limits?: OpenAICompatibleDirectTransportLimits;
	maxSteps?: number;
	tools?: ToolSet;
};

export function createOpenAICompatibleDirectTransport({
	connection: input,
	fetch,
	instructions,
	limits: inputLimits,
	maxSteps = 8,
	tools,
}: OpenAICompatibleDirectTransportOptions): ChatTransport<UIMessage> {
	const connection = requireOpenAICompatibleConnection(input);
	const limits = resolveOpenAICompatibleDirectTransportLimits(inputLimits);
	if (!Number.isInteger(maxSteps) || maxSteps < 1 || maxSteps > 20) {
		throw new Error('最大步骤数必须是 1 到 20 之间的整数。');
	}
	const secrets = [connection.apiKey ?? '', ...Object.values(connection.headers ?? {})].filter(Boolean);
	const baseFetch = fetch ?? globalThis.fetch;
	const safeFetch: typeof globalThis.fetch = async (request, init) => {
		try {
			return wrapBoundedResponse(await baseFetch(request, init), limits);
		} catch (error) {
			throw toSafeAgentError(error, secrets);
		}
	};
	const provider = createOpenAICompatible({
		apiKey: connection.apiKey?.trim() ? connection.apiKey : undefined,
		baseURL: connection.baseUrl,
		fetch: safeFetch,
		headers: withoutAuthorizationHeader(connection.headers),
		name: 'compatible-direct',
	});
	const agent = new ToolLoopAgent<never, ToolSet>({
		instructions,
		maxOutputTokens: limits.maxOutputTokens,
		maxRetries: limits.maxRetries,
		model: provider(connection.model),
		stopWhen: isStepCount(maxSteps),
		timeout: limits.timeout,
		tools: tools ?? {},
	} as ToolLoopAgentSettings<never, ToolSet>);
	const direct = new DirectChatTransport({
		agent,
		onError: (error) => toSafeAgentError(error, secrets).message,
	}) as unknown as ChatTransport<UIMessage>;
	return {
		async reconnectToStream(options) {
			try {
				const stream = await direct.reconnectToStream(options);
				return stream ? boundAndRedactStream(stream, secrets, limits) : null;
			} catch (error) {
				throw toSafeAgentError(error, secrets);
			}
		},
		async sendMessages(options) {
			try {
				return boundAndRedactStream(await direct.sendMessages(options), secrets, limits);
			} catch (error) {
				throw toSafeAgentError(error, secrets);
			}
		},
	};
}

function withoutAuthorizationHeader(headers?: Record<string, string>): Record<string, string> | undefined {
	if (!headers) return undefined;
	return Object.fromEntries(Object.entries(headers).filter(([name]) => name.toLowerCase() !== 'authorization'));
}

function boundAndRedactStream(
	stream: ReadableStream<UIMessageChunk>,
	secrets: readonly string[],
	limits: ResolvedOpenAICompatibleDirectTransportLimits,
) {
	const reader = stream.getReader();
	let chunks = 0;
	let projectionBytes = 0;
	return new ReadableStream<UIMessageChunk>({
		async pull(controller) {
			try {
				const result = await reader.read();
				if (result.done) {
					controller.close();
					return;
				}
				chunks += 1;
				if (chunks > limits.maxStreamChunks) {
					await cancelForLimit(reader);
					controller.error(new Error('模型输出事件数量超过客户端安全限制。'));
					return;
				}
				const remaining = limits.maxStreamProjectionBytes - projectionBytes;
				const measurement = measureAgentRuntimeValue(result.value, {
					maxArrayItems: 128,
					maxDataUrlBytes: Math.max(0, remaining),
					maxDepth: 16,
					maxNodes: 512,
					maxObjectKeys: 64,
					maxStringBytes: Math.max(0, remaining),
				});
				if (!measurement.success) {
					await cancelForLimit(reader);
					controller.error(new Error('模型输出内容超过客户端安全限制。'));
					return;
				}
				projectionBytes += measurement.stringBytes + measurement.dataUrlBytes;
				if (projectionBytes > limits.maxStreamProjectionBytes) {
					await cancelForLimit(reader);
					controller.error(new Error('模型输出内容超过客户端安全限制。'));
					return;
				}
				controller.enqueue(result.value);
			} catch (error) {
				controller.error(toSafeAgentError(error, secrets));
			}
		},
		cancel(reason) {
			return reader.cancel(reason);
		},
	});
}

async function cancelForLimit(reader: ReadableStreamDefaultReader<UIMessageChunk>) {
	await reader.cancel('stream limit exceeded').catch(() => undefined);
}

import type { ChatTransport, UIMessage } from 'ai';

export function bindAgentTransportGeneration<MESSAGE extends UIMessage>(
	transport: ChatTransport<MESSAGE>,
	generation: { current: number },
): ChatTransport<MESSAGE> {
	return {
		async reconnectToStream(options) {
			const current = generation.current;
			try {
				const stream = await transport.reconnectToStream(options);
				if (!stream) return null;
				return bindStreamGeneration(stream, current, generation);
			} catch (error) {
				if (generation.current !== current) return null;
				throw error;
			}
		},
		async sendMessages(options) {
			const current = generation.current;
			try {
				const stream = await transport.sendMessages(options);
				return bindStreamGeneration(stream, current, generation);
			} catch (error) {
				if (generation.current !== current) return emptyStream();
				throw error;
			}
		},
	};
}

function bindStreamGeneration<CHUNK>(
	stream: ReadableStream<CHUNK>,
	current: number,
	generation: { current: number },
): ReadableStream<CHUNK> {
	const reader = stream.getReader();
	return new ReadableStream<CHUNK>({
		async pull(controller) {
			if (generation.current !== current) {
				await reader.cancel('stale generation').catch(() => undefined);
				controller.close();
				return;
			}
			try {
				const result = await reader.read();
				if (generation.current !== current) {
					await reader.cancel('stale generation').catch(() => undefined);
					controller.close();
				} else if (result.done) controller.close();
				else controller.enqueue(result.value);
			} catch (error) {
				if (generation.current !== current) controller.close();
				else controller.error(error);
			}
		},
		cancel(reason) {
			return reader.cancel(reason);
		},
	});
}

function emptyStream<CHUNK>(): ReadableStream<CHUNK> {
	return new ReadableStream<CHUNK>({
		start(controller) {
			controller.close();
		},
	});
}

export type AgentToolApprovalResponse = {
	approved: boolean;
	id: string;
	reason?: string;
};

export type AgentToolApprovalResponder = (response: AgentToolApprovalResponse) => Promise<void>;

export function createAgentToolApprovalResponder(options: {
	beforeRespond?: (response: AgentToolApprovalResponse) => void | PromiseLike<void>;
	onError: (error: unknown) => void;
	respond: (response: AgentToolApprovalResponse) => void | PromiseLike<void>;
}): AgentToolApprovalResponder {
	const completed = new Set<string>();
	const pending = new Map<string, Promise<void>>();
	return (response) => {
		if (completed.has(response.id)) return Promise.resolve();
		const current = pending.get(response.id);
		if (current) return current;
		const request = Promise.resolve()
			.then(() => options.beforeRespond?.(response))
			.then(() => options.respond(response))
			.then(() => {
				completed.add(response.id);
			})
			.catch((error: unknown) => {
				options.onError(error);
				throw error;
			})
			.finally(() => {
				pending.delete(response.id);
			});
		pending.set(response.id, request);
		return request;
	};
}

'use client';

import { Check, Eye, EyeOff, RefreshCw, X } from 'lucide-react';
import type { ComponentPropsWithRef, FormEvent } from 'react';
import { useEffect, useId, useRef, useState } from 'react';
import { cn } from '@/lib/utils';
import type {
	ConnectionValidationIssue,
	OpenAICompatibleConnectionConfig,
	OpenAICompatibleConnectionDraft,
} from './connection-config';
import { validateOpenAICompatibleBaseUrl, validateOpenAICompatibleConnection } from './connection-config';
import { listOpenAICompatibleModels } from './model-list';
import { toSafeAgentError } from './safe-error';

export type OpenAICompatibleConnectionEditorMessages = {
	apiKey: string;
	apply: string;
	baseUrl: string;
	clearApiKey: string;
	hideApiKey: string;
	loadedModels: (count: number) => string;
	model: string;
	modelList: string;
	refreshModels: string;
	showApiKey: string;
};

export const defaultOpenAICompatibleConnectionEditorMessages: OpenAICompatibleConnectionEditorMessages = {
	apiKey: 'API Key',
	apply: '应用连接',
	baseUrl: 'Base URL',
	clearApiKey: '清除 API Key',
	hideApiKey: '隐藏 API Key',
	loadedModels: (count) => `已加载 ${count} 个模型`,
	model: '模型',
	modelList: '可用模型',
	refreshModels: '刷新模型',
	showApiKey: '显示 API Key',
};

export type OpenAICompatibleConnectionEditorProps = Omit<ComponentPropsWithRef<'form'>, 'onSubmit'> & {
	applied?: boolean;
	draft: OpenAICompatibleConnectionDraft;
	fetch?: typeof globalThis.fetch;
	messages?: Partial<OpenAICompatibleConnectionEditorMessages>;
	onApply: (connection: OpenAICompatibleConnectionConfig) => void;
	onDraftChange: (draft: OpenAICompatibleConnectionDraft) => void;
	revealIdentity?: number | string;
};

export function OpenAICompatibleConnectionEditor({
	applied = false,
	className,
	draft,
	fetch,
	messages,
	onApply,
	onDraftChange,
	revealIdentity,
	...props
}: OpenAICompatibleConnectionEditorProps) {
	const copy = { ...defaultOpenAICompatibleConnectionEditorMessages, ...messages };
	const modelListId = useId();
	const refreshController = useRef<AbortController | undefined>(undefined);
	const modelGeneration = useRef(0);
	const [showKey, setShowKey] = useState(false);
	const [models, setModels] = useState<string[]>([]);
	const [refreshing, setRefreshing] = useState(false);
	const [issues, setIssues] = useState<ConnectionValidationIssue[]>([]);
	const [requestError, setRequestError] = useState<string>();

	useEffect(() => {
		setShowKey(false);
	}, [revealIdentity]);

	useEffect(() => {
		modelGeneration.current += 1;
		refreshController.current?.abort();
		refreshController.current = undefined;
		setModels([]);
		setRefreshing(false);
		setRequestError(undefined);
	}, [draft.apiKey, draft.baseUrl, draft.headers, revealIdentity]);

	useEffect(
		() => () => {
			modelGeneration.current += 1;
			refreshController.current?.abort();
		},
		[],
	);

	function update<Key extends keyof OpenAICompatibleConnectionDraft>(
		key: Key,
		value: OpenAICompatibleConnectionDraft[Key],
	) {
		setIssues((current) => current.filter((issue) => issue.field !== key));
		setRequestError(undefined);
		if (key === 'apiKey' || key === 'baseUrl' || key === 'headers') {
			modelGeneration.current += 1;
			refreshController.current?.abort();
			refreshController.current = undefined;
			setModels([]);
			setRefreshing(false);
		}
		onDraftChange({ ...draft, [key]: value });
	}

	function apply(event: FormEvent<HTMLFormElement>) {
		event.preventDefault();
		const result = validateOpenAICompatibleConnection(draft);
		if (!result.success) {
			setIssues(result.issues);
			return;
		}
		setIssues([]);
		setRequestError(undefined);
		onApply(result.value);
	}

	async function refreshModels() {
		const baseUrl = validateOpenAICompatibleBaseUrl(draft.baseUrl);
		if (!baseUrl.success) {
			setIssues([{ field: 'baseUrl', message: baseUrl.message }]);
			return;
		}
		refreshController.current?.abort();
		const controller = new AbortController();
		const generation = modelGeneration.current + 1;
		modelGeneration.current = generation;
		refreshController.current = controller;
		setRefreshing(true);
		setRequestError(undefined);
		try {
			const result = await listOpenAICompatibleModels(
				{ apiKey: draft.apiKey, baseUrl: baseUrl.value, headers: draft.headers },
				{ fetch, signal: controller.signal },
			);
			if (refreshController.current !== controller || modelGeneration.current !== generation) return;
			setModels(result.map((model) => model.id));
		} catch (error) {
			if (!controller.signal.aborted) setRequestError(toSafeAgentError(error, [draft.apiKey ?? '']).message);
		} finally {
			if (refreshController.current === controller && modelGeneration.current === generation) {
				refreshController.current = undefined;
				setRefreshing(false);
			}
		}
	}

	const fieldError = (field: ConnectionValidationIssue['field']) =>
		issues.find((issue) => issue.field === field)?.message;
	return (
		<form
			data-slot='openai-compatible-connection-editor'
			data-applied={applied ? 'true' : 'false'}
			className={cn('bg-background grid min-w-0 gap-3 p-3 md:grid-cols-2', className)}
			onSubmit={apply}
			{...props}
		>
			<label className='form-control min-w-0 gap-1 md:col-span-2'>
				<span className='label-text text-xs'>{copy.baseUrl}</span>
				<input
					type='url'
					className='input input-bordered input-sm w-full'
					aria-invalid={Boolean(fieldError('baseUrl')) || undefined}
					autoCapitalize='none'
					autoComplete='url'
					placeholder='https://example.com/v1'
					spellCheck={false}
					value={draft.baseUrl}
					onChange={(event) => update('baseUrl', event.currentTarget.value)}
				/>
				<FieldError>{fieldError('baseUrl')}</FieldError>
			</label>
			<label className='form-control min-w-0 gap-1'>
				<span className='label-text text-xs'>{copy.apiKey}</span>
				<span className='join flex w-full'>
					<input
						type={showKey ? 'text' : 'password'}
						className='input input-bordered input-sm join-item min-w-0 flex-1'
						autoCapitalize='none'
						autoComplete='new-password'
						spellCheck={false}
						value={draft.apiKey ?? ''}
						onChange={(event) => update('apiKey', event.currentTarget.value)}
					/>
					<button
						type='button'
						className='btn btn-outline btn-sm join-item px-2'
						aria-label={showKey ? copy.hideApiKey : copy.showApiKey}
						title={showKey ? copy.hideApiKey : copy.showApiKey}
						onClick={() => setShowKey((value) => !value)}
					>
						{showKey ? <EyeOff aria-hidden='true' className='size-4' /> : <Eye aria-hidden='true' className='size-4' />}
					</button>
					<button
						type='button'
						className='btn btn-outline btn-sm join-item px-2'
						aria-label={copy.clearApiKey}
						title={copy.clearApiKey}
						disabled={!draft.apiKey}
						onClick={() => update('apiKey', '')}
					>
						<X aria-hidden='true' className='size-4' />
					</button>
				</span>
				<FieldError>{fieldError('apiKey')}</FieldError>
			</label>
			<label className='form-control min-w-0 gap-1'>
				<span className='label-text text-xs'>{copy.model}</span>
				<input
					type='text'
					list={modelListId}
					className='input input-bordered input-sm w-full'
					aria-invalid={Boolean(fieldError('model')) || undefined}
					autoCapitalize='none'
					spellCheck={false}
					placeholder='example-model'
					value={draft.model}
					onChange={(event) => update('model', event.currentTarget.value)}
				/>
				<datalist id={modelListId}>
					{models.map((model) => (
						<option key={model} value={model} />
					))}
				</datalist>
				<FieldError>{fieldError('model')}</FieldError>
			</label>
			{models.length > 0 ? (
				<label className='form-control min-w-0 gap-1 md:col-span-2'>
					<span className='label-text text-xs'>{copy.modelList}</span>
					<select
						className='select select-bordered select-sm w-full'
						aria-label={copy.modelList}
						value={models.includes(draft.model) ? draft.model : ''}
						onChange={(event) => update('model', event.currentTarget.value)}
					>
						<option value=''>{copy.loadedModels(models.length)}</option>
						{models.map((model) => (
							<option key={model}>{model}</option>
						))}
					</select>
				</label>
			) : null}
			{requestError ? (
				<div role='alert' className='text-error min-w-0 text-xs break-words md:col-span-2'>
					{requestError}
				</div>
			) : null}
			<div className='flex flex-wrap items-center justify-end gap-2 md:col-span-2'>
				<button
					type='button'
					className='btn btn-ghost btn-sm'
					disabled={refreshing}
					onClick={() => void refreshModels()}
				>
					<RefreshCw aria-hidden='true' className={cn('size-4', refreshing && 'animate-spin')} />
					{copy.refreshModels}
				</button>
				<button type='submit' className='btn btn-primary btn-sm'>
					<Check aria-hidden='true' className='size-4' />
					{copy.apply}
				</button>
			</div>
		</form>
	);
}

function FieldError({ children }: { children?: string }) {
	return children ? <span className='text-error text-xs'>{children}</span> : null;
}

'use client';

import { useChat } from '@ai-sdk/react';
import {
	type ChatOnFinishCallback,
	type ChatOnToolCallCallback,
	type Instructions,
	lastAssistantMessageIsCompleteWithApprovalResponses,
	type ToolSet,
	type UIMessage,
} from 'ai';
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import type { AgentMessagePartRenderContext } from '../../ui/agent-message';
import { AgentChat, type AgentChatProps, validateAgentRuntimeMessages } from '../agent-chat';
import type { OpenAICompatibleConnectionConfig } from './connection-config';
import { sameOpenAICompatibleConnection, validateOpenAICompatibleConnection } from './connection-config';
import { createOpenAICompatibleDirectTransport } from './direct-transport';
import type { OpenAICompatibleDirectTransportLimits } from './direct-transport-limits';
import {
	AgentRuntimeFileError,
	type AgentRuntimeFileLimits,
	convertAgentFilesToUIParts,
	resolveAgentRuntimeFileLimits,
} from './file-parts';
